// FleetServiceHandler is an implementation of the cloudidl.fleet.FleetService service.
type FleetServiceHandler interface {
	// Shared IsAdmin access only. Excludes values and provider credentials.
	GetDeploymentChartUpgradeStatus(context.Context, *connect.Request[fleet.GetDeploymentChartUpgradeStatusRequest]) (*connect.Response[fleet.GetDeploymentChartUpgradeStatusResponse], error)
	// Shared IsAdmin access only. Records evidence and closes unresolved ownership.
	ResolveDeploymentChartUpgrade(context.Context, *connect.Request[fleet.ResolveDeploymentChartUpgradeRequest]) (*connect.Response[fleet.ResolveDeploymentChartUpgradeResponse], error)
	// Admin-tenant caller identity only for provider metadata and support mutations;
	// service-mesh reachability alone is insufficient.
	GetDeploymentProviderInfo(context.Context, *connect.Request[fleet.GetDeploymentProviderInfoRequest]) (*connect.Response[fleet.GetDeploymentProviderInfoResponse], error)
	RefreshDeploymentProviderInfo(context.Context, *connect.Request[fleet.RefreshDeploymentProviderInfoRequest]) (*connect.Response[fleet.RefreshDeploymentProviderInfoResponse], error)
	RecoverDeployment(context.Context, *connect.Request[fleet.RecoverDeploymentRequest]) (*connect.Response[fleet.RecoverDeploymentResponse], error)
	UpdateAgentInstallationConfig(context.Context, *connect.Request[fleet.UpdateAgentInstallationConfigRequest]) (*connect.Response[fleet.UpdateAgentInstallationConfigResponse], error)
	// Requires MANAGE_CLUSTER. Does not start or reopen an installation phase.
	GetAgentInstallationInstructions(context.Context, *connect.Request[fleet.GetAgentInstallationInstructionsRequest]) (*connect.Response[fleet.GetAgentInstallationInstructionsResponse], error)
	CreateDeploymentTarget(context.Context, *connect.Request[fleet.CreateDeploymentTargetRequest]) (*connect.Response[fleet.CreateDeploymentTargetResponse], error)
	// Returns what the customer must run to connect their cluster. It is a read.
	// UNAVAILABLE: the provider has not produced the install yet; callers poll on
	// it. Every other code is terminal.
	StartAgentInstallation(context.Context, *connect.Request[fleet.StartAgentInstallationRequest]) (*connect.Response[fleet.StartAgentInstallationResponse], error)
	// CreateAwsInfrastructure records a Union-provisioned AWS dataplane request and
	// returns the CloudFormation quick-create link the customer must launch.
	CreateAwsInfrastructure(context.Context, *connect.Request[fleet.CreateAwsInfrastructureRequest]) (*connect.Response[fleet.CreateAwsInfrastructureResponse], error)
	// Admin only. Stores the full values snapshot derived from the published
	// archive. Retrying identical coordinates and content reuses the snapshot;
	// differing content is rejected.
	PublishChart(context.Context, *connect.Request[fleet.PublishChartRequest]) (*connect.Response[fleet.PublishChartResponse], error)
	// Admin only. Registers a published chart, assigns its template versions and
	// commits the provider plan event. A repeat registration returns
	// ALREADY_EXISTS without changing templates, associations or events.
	RegisterChart(context.Context, *connect.Request[fleet.RegisterChartRequest]) (*connect.Response[fleet.RegisterChartResponse], error)
	// Admin only. Updates catalog policy alone; artifact pins, template bindings
	// and historical snapshots are unchanged.
	SetChart(context.Context, *connect.Request[fleet.SetChartRequest]) (*connect.Response[fleet.SetChartResponse], error)
	// Admin only. Reads one template version, including its source.
	GetTemplate(context.Context, *connect.Request[fleet.GetTemplateRequest]) (*connect.Response[fleet.GetTemplateResponse], error)
	// Admin only. Lists template versions and their chart associations, without
	// source content.
	ListTemplates(context.Context, *connect.Request[fleet.ListTemplatesRequest]) (*connect.Response[fleet.ListTemplatesResponse], error)
	// Admin only. Replaces an existing version's content in place and advances
	// the template revision, preserving its chart associations. Every chart
	// assigned to that version renders from the new content.
	SetTemplate(context.Context, *connect.Request[fleet.SetTemplateRequest]) (*connect.Response[fleet.SetTemplateResponse], error)
	// Admin only. Renders stored or proposed templates against the affected
	// charts and clusters without writing state.
	ValidateChart(context.Context, *connect.Request[fleet.ValidateChartRequest]) (*connect.Response[fleet.ValidateChartResponse], error)
	// Admin only. Adopts targets' retained values edits from their user-update
	// history before an environment switches to stored templates. With
	// cluster_id, one target; without, every live Fleet target, a page at a
	// time. Each target's edits are derived and returned; with apply they are
	// recorded on its latest desired revision, leaving its values unchanged. A
	// target whose history is incomplete is reported for manual adoption.
	MigrateDeploymentEdits(context.Context, *connect.Request[fleet.MigrateDeploymentEditsRequest]) (*connect.Response[fleet.MigrateDeploymentEditsResponse], error)
	GetChart(context.Context, *connect.Request[fleet.GetChartRequest]) (*connect.Response[fleet.GetChartResponse], error)
	ListCharts(context.Context, *connect.Request[fleet.ListChartsRequest]) (*connect.Response[fleet.ListChartsResponse], error)
	// Requires MANAGE_CLUSTER on the cluster. Returns the latest desired revision,
	// including values YAML that may contain secrets.
	GetDeploymentValues(context.Context, *connect.Request[fleet.GetDeploymentValuesRequest]) (*connect.Response[fleet.GetDeploymentValuesResponse], error)
	// Requires MANAGE_CLUSTER on the cluster. Replaces the latest desired values
	// using optimistic concurrency and returns values YAML that may contain secrets.
	// Pass the revision returned by GetDeploymentValues unchanged as expected_revision;
	// the server owns advancing the revision, including on persisted render failures.
	UpdateDeploymentValues(context.Context, *connect.Request[fleet.UpdateDeploymentValuesRequest]) (*connect.Response[fleet.UpdateDeploymentValuesResponse], error)
	// Accepts the latest stored desired revision without creating a values revision.
	ApplyDeployment(context.Context, *connect.Request[fleet.ApplyDeploymentRequest]) (*connect.Response[fleet.ApplyDeploymentResponse], error)
	// Requires MANAGE_CLUSTER on the cluster. Returns a full revision, including
	// values YAML that may contain secrets.
	GetDeploymentRevision(context.Context, *connect.Request[fleet.GetDeploymentRevisionRequest]) (*connect.Response[fleet.GetDeploymentRevisionResponse], error)
	// Requires VIEW_FLYTE_EXECUTIONS on the cluster. Returns metadata without values YAML.
	ListDeploymentRevisions(context.Context, *connect.Request[fleet.ListDeploymentRevisionsRequest]) (*connect.Response[fleet.ListDeploymentRevisionsResponse], error)
	// Platform-admin or internal access only. The V0 handler returns UNIMPLEMENTED.
	RollbackDeployment(context.Context, *connect.Request[fleet.RollbackDeploymentRequest]) (*connect.Response[fleet.RollbackDeploymentResponse], error)
	// Reports every installation phase of a cluster, plus its reachability and
	// condition, as one point-in-time snapshot.
	GetLifecycleStatus(context.Context, *connect.Request[fleet.GetLifecycleStatusRequest]) (*connect.Response[fleet.GetLifecycleStatusResponse], error)
	// Shared IsAdmin access only. Reads captured diagnostics for one exact revision;
	// never renders values or returns values YAML.
	GetDeploymentRevisionRenderDiagnostics(context.Context, *connect.Request[fleet.GetDeploymentRevisionRenderDiagnosticsRequest]) (*connect.Response[fleet.GetDeploymentRevisionRenderDiagnosticsResponse], error)
}

